// PITFALL — try/catch doesn't catch async errors:
try {
  setTimeout(() => { throw new Error('async'); }, 0);
} catch(e) { console.log('never'); } // error is UNCAUGHT

// Promise — must use .catch:
Promise.reject('fail').catch(e => console.log('caught:', e));

// async/await — try/catch works:
async function run() {
  try { await Promise.reject('fail'); }
  catch(e) { console.log('caught:', e); }
}

async function failing() {
  throw new Error('boom');
}
async function handler() {
  try {
    await failing();
    console.log('after failing'); // ?
  } catch(e) {
    console.log('caught:', e.message);
    return 'recovered';
  }
}
handler().then(v => console.log('result:', v));

// Sync:
try {
  throw new Error('sync error');
} catch(e) { console.log(e.message); }

// Async — try/catch DOESN'T work here:
try {
  setTimeout(() => { throw new Error('async'); }, 0); // UNCAUGHT!
} catch(e) { console.log('never runs'); }

// Promise:
Promise.reject(new Error('oops'))
  .catch(e => console.log(e.message)); // works

// async/await:
async function run() {
  try {
    await Promise.reject(new Error('fail'));
  } catch(e) { console.log(e.message); } // works
}
